from xml.etree import ElementTree as ET

ROOT=Path(__file__).resolve().parents[1]
QA=ROOT/'qa'
OUT=QA/'evidence/final'

def xml_cases(name):
    result=[]
    for c in ET.parse(OUT/(name+'.xml')).iter('testcase'):
        failure=c.find('failure');error=c.find('error');skip=c.find('skipped')
        node=failure if failure is not None else error
        status='FAILED' if node is not None else 'SKIPPED' if skip is not None else 'PASSED'
        result.append({'suite':name,'case':c.get('classname','')+'::'+c.get('name',''),'name':c.get('name',''),'status':status,'detail':(node.text or '')[:500] if node is not None else '', 'evidence':f'qa/evidence/final/{name}.xml'})
    return result

cases=[]
for suite in ['backend','browser','http']:cases+=xml_cases(suite)
for suite in ['legacy-functional','legacy-reasoning','legacy-m9','legacy-smoke']:
    data=json.loads((OUT/(suite+'.json')).read_text())
    rows=data if isinstance(data,list) else data['results']
    for row in rows:cases.append({'suite':suite,'case':row['case'],'name':row['case'],'status':{'PASS':'PASSED','FAIL':'FAILED'}.get(row['status'],'SKIPPED'),'detail':row.get('error',row.get('detail',''))[:500],'evidence':f'qa/evidence/final/{suite}.json'})
for line in (OUT/'legacy-vault.log').read_text().splitlines():
    m=re.match(r'(PASS|FAIL) (VE\d+.*)',line)
    if m:cases.append({'suite':'legacy-vault','case':m[2],'name':m[2],'status':'PASSED' if m[1]=='PASS' else 'FAILED','detail':'','evidence':'qa/evidence/final/legacy-vault.log'})
execution=json.loads((OUT/'execution.json').read_text())
counts={k:sum(c['status']==k for c in cases) for k in ['PASSED','FAILED','SKIPPED']}
all_ok=counts['FAILED']==counts['SKIPPED']==0 and not any(execution['exitCodes'].values())

