# Evidence matrix: one row per executed case. No retry inflation or copied huge
# failure traces. External acceptance checks are separately marked NOT TESTED.
def mapping(case):
    matches=[f for f in features if any(p in case for p in [f['positiveScenario'],f['negativeScenario']])]
    if matches:return '/'.join(dict.fromkeys(m for f in matches for m in f['milestone'].split('/'))),'; '.join(f['feature'] for f in matches)
    lower=case.lower()
    for word,milestone,feature in [('household','M8','Household ownership and dependencies'),('m8','M8','Household intelligence'),('assistant','M9','AI guidance'),('chat','M9','AI guidance'),('gemini','M9','Deterministic provider integration'),('extraction','M4','Extraction and privacy'),('ocr','M4','Extraction and privacy'),('vault','M4','Document workspace'),('m5','M5','Saved preparations'),('preparation','M5','Saved preparations'),('expiry','M7','Deadline and expiry'),('passport','M3/M5','Passport rules and journey'),('workflow','M7','Citizen workflows'),('reasoning','M7','Advanced reasoning'),('optimizer','M7','Correction optimizer'),('planner','M6','Resolution planner'),('intelligence','M4/M6/M7','Intelligence contracts')]:
        if word in lower:return milestone,feature
    return 'M1/M2/M3','Foundation and navigation'
with (QA/'M1-M9_FINAL_TEST_MATRIX.csv').open('w',newline='') as file:
    writer=csv.writer(file);writer.writerow(['Milestone','Feature','TestCase','TestType','ExpectedResult','ActualResult','Status','EvidencePath','Notes'])
    for c in cases:
        milestone,feature=mapping(c['case'])
        writer.writerow([milestone,feature,c['case'],'Backend pytest' if c['suite']=='backend' else 'HTTP integration' if c['suite']=='http' else 'Chromium E2E','All scenario assertions pass',c['detail'] or 'All assertions passed',c['status'],c['evidence'],'Fictional local data; final run only'])
    writer.writerow(['M1-M9','Frontend production compilation','TypeScript + Vite','Build','Compilation and bundling succeed',summary['build'],summary['build'],'qa/evidence/final/frontend-build.log','Build not counted as a test case'])
    for scope in ['Live Gemini','Live OCR','Government rule freshness','Production hosting/security']:
        writer.writerow(['External',scope,scope,'External integration','Separate authorized verification','Not run in this local session','NOT TESTED','qa/REMAINING_EXTERNAL_DEPENDENCIES.md','Excluded from passing and skipped-test counts'])

requests=[]
